{
  "handle": "AtomicBid#4b82",
  "mechanism": "A coordination primitive that bundles a Bid#d3e6 (intent/cost) and an Act#ffef (execution) into a single, indivisible turn. Unlike a standard Bid#d3e6 which halts for approval, AtomicBid treats the Bid as an immutable Audit#4044 log entry and proceeds immediately to execution. Similar to LazyConsensus#a1e9 for state, it assumes optimistic permission but remains subject to retroactive Compensate#9bfb if the Bid is rejected post-hoc.",
  "gloss": "Declaration and execution in a single turn",
  "invariants": [
    "Turn Indivisibility: The Bid and the Tool Call MUST occur in the same message/turn.",
    "Auditability: The Bid MUST precede the Action in the log.",
    "Revocability: The Action must be reversible (or low-stakes) to allow for Compensation."
  ],
  "failure_modes": [
    "Permission Race: Executing an irreversible high-stakes action before the Orchestrator can veto.",
    "Log Drift: Generating the Action but failing to generate the Bid, breaking the audit trail."
  ],
  "_meta": {
    "tier": 2,
    "layer": "Society",
    "category": "Economics",
    "ring": 1
  },
